public static void main(String[] args) {
    // 自分の得意な言語で
    // Let's チャレンジ！！
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt(), A = sc.nextInt();
    int[] T = new int[N + 1];
    for (int i = 1; i <= N; i++) {
      T[i] = sc.nextInt();
    }
    int lastFinishTime = 0;
    for (int i = 1; i <= N; i++) {
      if (T[i] >= lastFinishTime) {
        lastFinishTime = T[i] + A;
      } else {
        lastFinishTime += A;
      }
      System.out.println(lastFinishTime);
    }
}

